mapper.select:
select m.menu_id, m.menu_name, m.parent_id, m.order_num, m.path, m.component, m.is_frame, m.menu_type,
m.visible, IFNULL(m.perms,'') as perms, m.icon, m.create_time, m.remark,m.perm_url,m.menu_classify,m.menu_apply,m.`status`,
m.file_url, i.industry_name, m.industry_code
from sys_menu m
LEFT JOIN sys_industry_conf i on m.industry_code = i.industry_code and i.accept_node = #{acceptNode}  and i.delete_flag = 0


		AND m.menu_name like CONCAT(CONCAT('%', #{menuName}),'%')


		AND m.visible = #{visible}


		AND m.status = #{status}


		AND

			m.menu_classify like concat('%',#{item},'%')



		AND m.menu_classify=#{menuClassifyEq}


		AND m.menu_apply = #{menuApply}


		AND m.industry_code = #{industryCode}


		AND m.parent_id in

			#{item}



		AND m.menu_id not in

			#{item}



order by m.parent_id,m.order_num

select distinct m.menu_id, m.parent_id, m.menu_name, m.path,m.`status`, m.component, m.visible, IFNULL(m.perms,'') as perms, m.is_frame, m.menu_type, m.icon, m.order_num, m.create_time,m.remark,m.menu_classify,menu_apply
from sys_menu m where (m.menu_type in ('M', 'C') and m.visible = '0'  and m.`status`='0'

	and m.menu_apply

		#{item}


 ) or m.path='/indexPermission'
order by m.parent_id, m.order_num

select * from ( select DISTINCT me.menu_id, me.parent_id, me.menu_name, me.path, me.component, me.visible, IFNULL( me.perms, '' ) AS perms, me.is_frame, me.menu_type, me.icon, me.order_num, me.create_time, me.remark, me.menu_classify, me.menu_apply,me.`status`,me.FILE_URL from sys_menu me inner join ( SELECT DISTINCT m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.visible, IFNULL( m.perms, '' ) AS perms, m.is_frame, m.menu_type, m.icon, m.order_num, m.create_time, m.remark, m.menu_classify, m.menu_apply, m.`status`, m.file_url FROM sys_menu m inner JOIN (SELECT ria.role_id, ia.menu_id FROM sys_role_industry_auth ria INNER JOIN sys_industry_auth ia ON ria.auth_id = ia.auth_id WHERE 1=1
and ia.industry_code = #{industryCode}
and ia.app_ver_code = #{appVerCode}
) tmp ON tmp.menu_id = m.menu_id LEFT JOIN sys_role r ON r.role_id = tmp.role_id LEFT JOIN sys_user_role ur ON ur.role_id = tmp.role_id where ur.user_id = #{userId} and ((m.menu_type in ('M', 'C') and m.visible = '0' AND r.status = 0 and m.`status`='0'
and m.MENU_CLASSIFY like CONCAT('%', '0', '%')
and m.MENU_CLASSIFY like CONCAT('%', '0', '%')
and m.menu_apply
#{item}
) or (m.path='/indexPermission') ) ) a on a.parent_id = me.menu_id and me.MENU_TYPE = 'M' union SELECT DISTINCT m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.visible, IFNULL( m.perms, '' ) AS perms, m.is_frame, m.menu_type, m.icon, m.order_num, m.create_time, m.remark, m.menu_classify, m.menu_apply, m.`status`, m.file_url FROM sys_menu m inner JOIN (SELECT ria.role_id, ia.menu_id FROM sys_role_industry_auth ria INNER JOIN sys_industry_auth ia ON ria.auth_id = ia.auth_id WHERE 1=1
and ia.industry_code = #{industryCode}
and ia.app_ver_code = #{appVerCode}
) tmp ON tmp.menu_id = m.menu_id LEFT JOIN sys_role r ON r.role_id = tmp.role_id LEFT JOIN sys_user_role ur ON ur.role_id = tmp.role_id where ur.user_id = #{userId} and ((m.menu_type in ('M', 'C') and m.visible = '0' AND r.status = 0 and m.`status`='0'
and m.MENU_CLASSIFY like CONCAT('%', '0', '%')
and m.MENU_CLASSIFY like CONCAT('%', '1', '%')
and m.menu_apply
#{item}
) or (m.path='/indexPermission') )) m order by m.parent_id, m.order_num

SELECT DISTINCT m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.visible, IFNULL( m.perms, '' ) AS perms, m.is_frame, m.menu_type, m.icon, m.order_num, m.create_time, m.remark, m.menu_classify, m.menu_apply, m.`status`, m.file_url FROM sys_menu m inner JOIN (SELECT ria.role_id, ia.menu_id FROM sys_role_industry_auth ria INNER JOIN sys_industry_auth ia ON ria.auth_id = ia.auth_id WHERE 1=1
and ia.industry_code = #{industryCode}
and ia.app_ver_code = #{appVerCode}
) tmp on tmp.menu_id = m.menu_id LEFT JOIN sys_role r ON r.role_id = tmp.role_id
LEFT JOIN sys_user_role ur ON ur.role_id = tmp.role_id
where ((m.menu_type = #{menuType} and m.visible = '0' AND r.status = 0 and m.`status`='0'
and m.MENU_CLASSIFY like CONCAT('%', '0', '%')
and m.MENU_CLASSIFY like CONCAT('%', '1', '%')
and m.menu_apply
#{item}
) or (m.path='/indexPermission') )
and ur.user_id = #{userId}
and m.menu_id
#{item}

SELECT DISTINCT concat_ws(',', a.perms, b.perms, c.perms) AS perms FROM sys_user_role ur JOIN sys_role r ON r.role_id = ur.role_id AND r.del_flag = '0' JOIN sys_role_industry_auth ria ON ria.role_id = r.role_id JOIN sys_industry_auth ia ON ia.auth_id = ria.auth_id AND ia.industry_code = #{industryCode} AND ia.app_ver_code = #{appVerCode} JOIN sys_menu a ON a.menu_id = ia.menu_id AND a.status = '0' AND (a.visible = '0' OR a.industry_code = '660000') AND a.menu_apply
#{item}
LEFT JOIN sys_menu b ON b.menu_id = a.parent_id AND b.status = '0' AND (b.visible = '0' OR b.industry_code = '660000') AND b.menu_apply
#{item}
LEFT JOIN sys_menu c ON c.menu_id = b.parent_id AND c.status = '0' AND (c.visible = '0' OR c.industry_code = '660000') AND c.menu_apply
#{item}
WHERE ur.user_id = #{userId}

select m.menu_id, m.menu_name, m.parent_id, m.order_num, m.path, m.component, m.is_frame, m.menu_type, m.visible, IFNULL(m.perms,'') as perms, m.icon, m.create_time, m.remark,m.perm_url,m.menu_classify,m.menu_apply,m.`status`, m.file_url, i.industry_name as industryName, m.industry_code from sys_menu m LEFT JOIN sys_industry_conf i on m.industry_code = i.industry_code and i.delete_flag = 0
and i.accept_node = #{configValue}
where m.menu_id = #{menuId}

