menu_name = #{menuName}, parent_id = #{parentId}, order_num = #{orderNum}, path = #{path}, component = #{component}, perm_url = #{permUrl}, is_frame = #{isFrame}, menu_type = #{menuType}, visible = #{visible}, perms = #{perms}, icon = #{icon}, remark = #{remark}, menu_classify = #{menuClassify}, menu_apply = #{menuApply}, UPDATE_BY = #{modifier}, status = #{status}, file_url = #{fileUrl}, industry_code = #{industryCode}, update_time = #{updateTime}
where menu_id = #{menuId}

update sys_menu
menu_name = #{menuName}, order_num = #{orderNum}, path = #{path}, component = #{component}, perm_url = #{permUrl}, is_frame = #{isFrame}, menu_type = #{menuType}, visible = #{visible}, perms = #{perms}, icon = #{icon}, remark = #{remark}, menu_classify = #{menuClassify}, menu_apply = #{menuApply}, UPDATE_BY = #{modifier}, status = #{status}, file_url = #{fileUrl}, industry_code = #{industryCode}, update_time = #{updateTime}
where parent_id = #{parentId}

